-- 1. Insert Kos-Kosan Syariat Article
INSERT INTO published_articles (
  slug, title, excerpt, body, channel, tags_json, sources_json, author, published_at, image_url
) VALUES (
  'cara-memulai-bisnis-kos-kosan-milenial-yang-sesuai-syariat',
  'Cara Memulai Bisnis Kos-Kosan Milenial yang Sesuai Syariat',
  'Raih passive income berkah tanpa riba! Simak panduan lengkap cara memulai bisnis kos-kosan syariah yang aman, estetik, dan diminati generasi milenial.',
  '["Siapa yang tidak tergiur melihat tren passive income di TikTok? Banyak kreator muda yang dengan bangganya memamerkan kebebasan finansial mereka hanya dengan bermodalkan bisnis sewa properti, khususnya kos-kosan. Bisa liburan ke mana saja, bekerja santai dari kafe, sementara uang kos bulanan mengalir terus ke rekening.", "Namun, di balik gaya hidup tersebut, banyak bisnis kos-kosan yang beralih menjadi kos bebas (campur pria dan wanita tanpa pengawasan) demi menarik lebih banyak penyewa. Sebagai seorang muslim, tentu kita sadar bahwa kekayaan bukan sekadar soal angka, tapi soal keberkahan.", "Bisakah kita meraup cuan maksimal dari bisnis kos-kosan milenial, namun tetap menjaga syariat dan bebas dari pergaulan bebas? Tentu saja! Mari kita bahas caranya secara mendalam.", "## Mengapa Bisnis Kos-Kosan Sangat Menjanjikan di 2026?", "Seiring dengan kembalinya aktivitas normal pasca-pandemi dan tren hybrid working, tingkat mobilitas anak muda dan pekerja kantoran (terutama Generasi Z) di kota-kota besar semakin tinggi. Mereka lebih memilih menyewa kos yang dekat dengan pusat bisnis atau kampus daripada menghabiskan waktu berjam-jam menembus kemacetan. Tingginya permintaan (demand) inilah yang membuat bisnis indekos seolah tidak ada matinya.", "## Mengapa Harus Mengusung Konsep Kos Syariah?", "Mungkin Anda khawatir: \"Kalau aturannya ketat, nanti kosannya sepi.\" Padahal, realitanya justru sebaliknya! Kos berkonsep syariah kini menjadi buruan utama di wilayah perkotaan.", "### Tiga Manfaat Utama Konsep Kos Syariah:", "1. **Tingginya Permintaan Khusus:** Banyak orang tua mahasiswa dan pekerja muslim yang rela membayar lebih mahal asalkan mendapatkan lingkungan kos yang aman, tenang, dan terjaga privasinya.", "2. **Keberkahan Harta:** Menyewakan properti berarti Anda memfasilitasi kegiatan penyewa. Membiarkan properti Anda menjadi tempat maksiat (pergaulan bebas, miras, dll) sama dengan membiarkan aliran dosa jariyah. Kos syariah memastikan passive income Anda bersih dan membawa berkah.", "3. **Penyewa Lebih Berkualitas:** Penyewa yang mencari kos syariah umumnya memiliki karakter yang lebih rapi, tenang, dan bertanggung jawab terhadap perawatan fasilitas properti Anda.", "## Empat Langkah Praktis Memulai Bisnis Kos Syariah ala Milenial", "Berikut adalah langkah-langkah strategis memulai bisnis kos syariah yang laris manis di kalangan milenial:", "### 1. Menentukan Lokasi Strategis", "Lokasi adalah nyawa dari bisnis properti. Carilah lahan atau rumah di dekat area kampus, kawasan industri, atau perkantoran. Tidak harus di pinggir jalan raya besar; masuk gang sedikit tidak masalah asalkan akses motor mudah dan lingkungannya aman.", "### 2. Desain Estetik & Instagramable", "Milenial dan Gen Z sangat peduli dengan estetika. Anda tidak perlu membangun kos yang mewah bak hotel bintang lima. Cukup usung konsep minimalis, clean look (seperti gaya Japandi atau Industrial), sirkulasi udara yang baik, dan furnitur fungsional. Kamar kos yang terang dan rapi akan sangat cepat laku saat dipasarkan melalui TikTok atau Instagram.", "### 3. Buat Aturan yang Jelas Namun Ramah", "Label syariah bukan berarti kos Anda harus bernuansa pesantren yang kaku. Buatlah aturan tertulis yang tegas di awal (misal: larangan membawa tamu lawan jenis ke dalam kamar, jam malam untuk tamu), tetapi sampaikan dengan cara komunikasi yang ramah. Sediakan ruang tamu terbuka (communal space) agar penyewa tetap bisa menerima tamu dengan sopan tanpa melanggar privasi.", "### 4. Manfaatkan Teknologi Digital", "Pasang CCTV di area publik untuk keamanan, gunakan smart lock di pintu gerbang, dan pasarkan kos Anda melalui platform digital (TikTok, Instagram Reels, Mamikos). Visualisasikan kebersihan dan kenyamanan kos syariah Anda.", "## Kesimpulan dan Catatan Sumber Resmi", "Menjalankan bisnis kos-kosan di era sekarang bukan sekadar berburu passive income. Pandanglah bisnis ini sebagai ladang amal jariyah: Anda menyediakan tempat bernaung yang aman, bersih, dan menenangkan bagi para musafir, perantau, atau penuntut ilmu.", "Dengan desain kamar yang kekinian dipadukan dengan aturan syariat yang menenangkan, kos-kosan Anda tidak hanya akan diserbu oleh generasi milenial, tetapi juga mengalirkan rezeki yang berkah dunia dan akhirat.", "---", "*Artikel properti ini diterbitkan oleh Redaksi AnekaNews berdasarkan dokumen panduan investasi properti syariah dan laporan tren hunian milenial 2026.*"]',
  'rumah-properti',
  '["Bisnis Kos Syariah", "Kos Milenial", "Properti Syariah 2026", "Passive Income Halal", "Investasi Kosan"]',
  '["https://pu.go.id", "https://kemenkeu.go.id"]',
  'Redaksi AnekaNews',
  datetime('now'),
  '/images/harga-properti-naik-tren-rumah-hemat-milenial-2026.jpg'
);

-- 2. Insert House Flipping TikTok Article (Unique Content!)
INSERT INTO published_articles (
  slug, title, excerpt, body, channel, tags_json, sources_json, author, published_at, image_url
) VALUES (
  'mengenal-tren-house-flipping-di-tiktok-hukum-syariah',
  'Mengenal Tren ''House Flipping'' di TikTok: Bagaimana Hukumnya Secara Syariah?',
  'Mulai tertarik bisnis house flipping yang viral di TikTok? Pelajari hukum beli rumah rusak untuk dijual mahal secara syariah agar investasi properti Anda tetap halal & berkah.',
  '["Belakangan ini, linimasa TikTok dan media sosial lainnya sering diramaikan oleh video before-after yang memukau. Pemuda atau konten kreator membeli sebuah rumah tua yang nyaris hancur dengan harga murah, menyulapnya menjadi hunian modern nan estetik, lalu menjualnya kembali dengan harga berlipat ganda. Fenomena ini dikenal dengan istilah house flipping.", "Melihat potensi keuntungannya yang sangat besar dan cepat (cuan besar), banyak generasi muda yang tergiur mencoba bisnis ini. Namun, sebagai seorang Muslim, pertanyaan terbesarnya adalah: Bagaimana hukum bisnis house flipping secara syariat? Apakah mengambil untung besar dari renovasi rumah diperbolehkan, atau justru mendekati riba dan penipuan?", "Mari kita bedah tren ini dari kacamata bisnis dan syariah secara lengkap.", "## Apa Itu Bisnis House Flipping?", "Secara sederhana, house flipping adalah strategi investasi properti jangka pendek dengan konsep buy-fix-sell (beli, perbaiki, jual). Investor mencari properti undervalued (di bawah harga pasar), biasanya karena kondisinya rusak, disita bank, atau pemilik butuh uang cepat.", "Setelah dibeli, rumah tersebut direnovasi sedemikian rupa mulai dari pengecatan, perbaikan atap, hingga penataan ulang interior untuk meningkatkan daya tariknya. Dalam waktu singkat (beberapa bulan), rumah dijual kembali sesuai atau sedikit di atas harga pasar. Mengingat tren properti di tahun 2026 yang kian mengutamakan desain estetik (seperti Japandi atau minimalis), house flipping bisa mendatangkan profit puluhan hingga ratusan juta rupiah per unit.", "## Hukum House Flipping dalam Pandangan Syariat Islam", "Secara prinsip dasar muamalah (hukum perdagangan dalam Islam), jual beli properti adalah halal dan mubah. Namun, praktik house flipping bisa menjadi bermasalah jika melanggar rambu-rambu berikut:", "### 1. Etika Menetapkan Harga (Menghindari Ghabn Faahisy)", "Apakah menaikkan harga jual terlalu tinggi diperbolehkan? Dalam Islam, mengambil keuntungan (margin) dari jual beli tidak memiliki batasan persentase mutlak asalkan atas dasar suka sama suka (an taradin). Akan tetapi, Islam melarang Ghabn Faahisy (penipuan harga yang terlampau jauh dari harga wajar di pasaran), apalagi jika pembeli awam tentang harga properti. Selama harga jual setelah renovasi masih wajar sesuai dengan harga pasaran di lingkungan tersebut dan sebanding dengan nilai tambah (renovasi) yang diberikan, maka keuntungannya halal.", "### 2. Pentingnya Transparansi (Tidak Menyembunyikan Cacat)", "Ini adalah godaan terbesar flipper. Kadang, untuk menghemat biaya renovasi, perbaikan dilakukan seadanya (asal terlihat bagus dari luar) untuk menutupi kerusakan parah (seperti rayap di rangka atap atau kebocoran tersembunyi). Menjual barang dengan menyembunyikan cacat (Tadlis) sangat dilarang dalam Islam. Rasulullah SAW bersabda: \"Barangsiapa yang menipu kami, maka ia bukan golongan kami\" (HR. Muslim). Seorang flipper muslim wajib jujur menjelaskan apa saja yang direnovasi dan jika ada kekurangan yang belum terselesaikan.", "## 3 Tips Menjalankan House Flipping yang Amanah dan Untung Besar", "Bagi Anda yang ingin menjajal peruntungan di tren ini, pastikan bisnis Anda membawa keberkahan dengan tiga prinsip ini:", "### 1. Riset Lokasi dan Potensi Kenaikan Harga", "Pastikan Anda tidak sembarang membeli rumah rusak. Pilihlah lokasi di area sunrise property (sedang berkembang) atau yang memiliki akses bagus ke fasilitas umum. Rumah sejelek apa pun, jika lokasinya strategis, akan sangat mudah dijual setelah direnovasi.", "### 2. Mengatur Budget Renovasi Secara Rasional", "Kunci sukses flipping ada pada efisiensi renovasi. Hindari merombak total struktur jika tidak perlu. Fokus pada wajah rumah: fasad depan, dapur, dan kamar mandi. Selalu sediakan dana cadangan (sekitar 10-20% dari total budget) untuk biaya tak terduga.", "### 3. Hindari Modal dari Riba (KPR Konvensional)", "Banyak flipper gagal karena tercekik bunga pinjaman bank konvensional yang terus berjalan saat rumah belum laku. Carilah modal dari tabungan, sistem syirkah (patungan/kerja sama bagi hasil dengan investor), atau pembiayaan dari bank syariah dengan akad yang jelas (seperti Murabahah atau Musyarakah Mutanaqishah).", "## Kesimpulan", "Tren house flipping bukan sekadar cara cepat menjadi kaya, melainkan peluang bisnis nyata yang menjanjikan. Dalam kacamata Islam, bisnis ini halal dan bahkan bisa bernilai ibadah jika dilakukan dengan niat menyediakan hunian yang layak, bersih, dan indah bagi keluarga Muslim lainnya.", "Yang terping, jaga kejujuran dalam bertransaksi, hindari menutupi cacat rumah, dan jauhi modal riba. Dengan cara ini, keuntungan besar yang Anda dapatkan tidak hanya bernilai materi di dunia, tetapi juga membawa keberkahan untuk akhirat.", "---", "*Artikel hukum properti syariah ini diterbitkan oleh Redaksi AnekaNews berdasarkan tinjauan akad muamalah keuangan Islam 2026.*"]',
  'rumah-properti',
  '["House Flipping", "TikTok Properti", "Investasi Syariah", "Flipping Rumah", "Hukum Muamalah"]',
  '["https://kemenkeu.go.id", "https://mui.or.id"]',
  'Redaksi AnekaNews',
  datetime('now'),
  '/images/millennial-eco-house-2026.jpg'
);

